最小实现要按事件名保存回调集合，订阅时返回取消函数，发布时用集合快照逐个调用，避免回调在通知期间退订而打乱遍历。一次性订阅可在首次执行后自行取消。一个订阅者抛错可能阻止后续订阅者，因此可逐个捕获并统一上报，但不能静默吞错。

### 本题专属实现

```ts
type ShopEvents = {
  'favorite:changed': { productId: string; active: boolean }
  'coupon:expired': { couponId: string }
}
class EventHub<E extends Record<string, unknown>> {
  private slots = new Map<keyof E, Set<(value: any) => void>>()
  on<K extends keyof E>(name: K, fn: (value: E[K]) => void) {
    const set = this.slots.get(name) ?? new Set()
    set.add(fn); this.slots.set(name, set)
    return () => {
      set.delete(fn)
      if (!set.size) this.slots.delete(name)
    }
  }
  emit<K extends keyof E>(name: K, value: E[K]) {
    for (const fn of [...(this.slots.get(name) ?? [])]) {
      try { fn(value) } catch (e) { console.error(name, e) }
    }
  }
}
const hub = new EventHub<ShopEvents>()
const off = hub.on('favorite:changed', e => console.log(e.productId))
hub.emit('favorite:changed', { productId: 'sku-9', active: true })
off()
```

