**短答：**实现一个最小 MVVM，关键不是把 DOM 和对象双向绑死，而是让 ViewModel 成为可观察状态、模板依赖与用户事件之间的协调层。数据读取时收集依赖，数据写入时只通知相关更新任务；表单事件再显式回写状态，便形成双向体验。

### 本题实现步骤

1. 响应式包装器在 `get` 时收集“目标—键—effect”，在 `set` 时通知任务。
2. 模板编译成渲染 effect；表单事件再回写状态。
3. 调度器合并同轮写入；卸载时停止 effect 与监听。

### 一个最小实现

```js
let activeEffect, deps = new WeakMap()
function reactive(obj) {
  return new Proxy(obj, {
    get(o, k, r) {
      if (activeEffect) {
        let m = deps.get(o) || (deps.set(o, new Map()), deps.get(o))
        let set = m.get(k) || (m.set(k, new Set()), m.get(k))
        if (!set.has(activeEffect)) {
          if (!set.has(activeEffect)) {
          set.add(activeEffect)
          activeEffect.deps.push(set)
        }
          activeEffect.deps.push(set)
        }
      }
      return Reflect.get(o, k, r)
    },
    set(o, k, v, r) {
      const old = o[k], ok = Reflect.set(o, k, v, r)
      if (ok && !Object.is(old, v)) new Set(deps.get(o)?.get(k) || []).forEach(runner => runner())
      return ok
    }
  })
}
function effect(fn) {
  const runner = () => {
    runner.deps.forEach(set => set.delete(runner))
    runner.deps.length = 0
    const parent = activeEffect
    activeEffect = runner
    try { fn() } finally { activeEffect = parent }
  }
  runner.deps = []
  runner()
}
const state = reactive({ nickname: '海盐' })
effect(() => { preview.textContent = state.nickname })
input.oninput = e => { state.nickname = e.target.value }
