  498      yield this.observability.beginTurn(iteration);
  499      yield* this.hookRunner.runIterationHook('beforeIteration', iteration);
  500      yield* this.prelude.emitPendingEnvironmentContext();
  501      yield* this.prelude.emitPendingAgentProfile();
  502      if (yield* this.runCompactionPhase()) return null;
  503      // ：host 消息注入（run-observations / thread-notifications）已迁到
  504      // beforeModel 默认策略栈——注入槽位不变（compaction 之后、LLM 调用之前）。
