  189    async embedPassages(texts: string[]): Promise<(Float32Array | null)[]> {
  190      const result: (Float32Array | null)[] = new Array(texts.length).fill(null);
  191      const missIndexes: number[] = [];
  192  
  193      for (let i = 0; i < texts.length; i++) {
  194        const vec = this.cache.get(this.passageHash(texts[i]));
  195        if (vec) {
  196          result[i] = vec;
  197        } else {
  198          missIndexes.push(i);
  199        }
  200      }
  201      if (missIndexes.length === 0 || !this.ready) return result;
  202  
  203      try {
  204        const vecs = await this.backend.embed(
  205          missIndexes.map((i) => `${PASSAGE_PREFIX}${texts[i]}`),
  206        );
  207        missIndexes.forEach((textIndex, k) => {
  208          result[textIndex] = vecs[k];
  209          this.cache.set(this.passageHash(texts[textIndex]), vecs[k]);
  210        });
  211        this.scheduleFlush();
  212      } catch (err) {
  213        this.log(`[local-embedding] 候选推理失败：${err instanceof Error ? err.message : String(err)}`);
  214      }
  215      return result;
