  101   * @param partialJson The partial JSON string from streaming
  102   * @returns Parsed object or empty object if parsing fails
  103   */
  104  export function parseStreamingJson<T = Record<string, unknown>>(partialJson: string | undefined): T {
  105  	if (!partialJson || partialJson.trim() === "") {
  106  		return {} as T;
  107  	}
