  111  /**
  112   * abort 后 drain 白名单收尾事件的硬上限。超时则放弃继续读 generator，
  113   * 避免旧轮卡住插队/下轮开跑（ promote 延迟）。
  114   */
  115  const ABORT_DRAIN_DEADLINE_MS = 1_500
  116  
  117  /**
  118   * abort 信号已置位后，继续 drain runtime generator 并只 emit 非 terminal 的
  119   * 白名单收尾事件，确保 partial persist / envelope 收尾进入 transcript；最终
  120   * terminal 由 host 统一发出。硬超时后放弃继续 drain。
  121   */
  122  async function drainAbortTerminalEvents(
  123    generator: AsyncIterable<StreamEvent>,
  124    deliveryTurn: DeliveryTurn,
  125    firstEvent: StreamEvent,
  126  ): Promise<void> {
  127    if (isAbortTerminalEvent(firstEvent)) {
  128      await deliveryTurn.emit(firstEvent)
  129    }
  130    let timer: ReturnType<typeof setTimeout> | undefined
  131    const deadline = new Promise<'timeout'>((resolve) => {
  132      timer = setTimeout(() => resolve('timeout'), ABORT_DRAIN_DEADLINE_MS)
  133    })
  134    const drain = (async (): Promise<'done'> => {
  135      for await (const event of generator) {
  136        if (isAbortTerminalEvent(event)) {
  137          await deliveryTurn.emit(event)
  138        }
  139      }
  140      return 'done'
  141    })()
  142    try {
  143      await Promise.race([drain, deadline])
  144    } finally {
  145      if (timer) clearTimeout(timer)
  146    }
  147  }
```

